export const generateRetentionDraftsResponseStatsFoundMin = 0;

export const generateRetentionDraftsResponseStatsVerifiedMin = 0;

export const generateRetentionDraftsResponseStatsNewLtpPlayersMin = 0;

export const generateRetentionDraftsResponseStatsCreatedMin = 0;

export const generateRetentionDraftsResponseStatsSkippedMin = 0;

export const generateRetentionDraftsResponseStatsNeedsContextMin = 0;

export const generateRetentionDraftsResponseStatsManualEditMin = 0;

export const generateRetentionDraftsResponseStatsErrorCountMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonNoPhoneMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonOptedOutMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonDuplicateMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonHoldoutMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonMarketingConsentMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonMissingPlayerMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonInvalidTriggerMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonOutOfWindowMin = 0;

export const generateRetentionDraftsResponseStatsSkippedByReasonAlreadyReturnedMin = 0;

export const generateRetentionDraftsResponseDraftsItemContextClassmatesSignedUpMin = 0;

export const generateRetentionDraftsResponseDraftsItemContextLookbackDaysMax = 30;

export const generateRetentionDraftsResponseDraftsItemContextLtpTextSeedNonceMin = 0;

export const generateRetentionDraftsResponseDraftsItemContextLtpTextSlotIndicesMinOne = 0;

export const GenerateRetentionDraftsResponse = zod.object({
  schema_ready: zod.boolean(),
  lookback_days: zod
    .number()
    .min(1)
    .max(generateRetentionDraftsResponseLookbackDaysMax)
    .describe(
      "Effective lookback after values above 30 are clamped to 30; defaults to 3",
    ),
  created: zod.number(),
  skipped: zod.number(),
  needs_context: zod
    .number()
    .min(generateRetentionDraftsResponseNeedsContextMin),
  manual_edit: zod.number().min(generateRetentionDraftsResponseManualEditMin),
  errors: zod
    .array(zod.string())
    .describe(
      "Per-candidate or generation failures; errors are not included in skipped",
    ),
  stats: zod
    .object({
      found: zod.number().min(generateRetentionDraftsResponseStatsFoundMin),
      verified: zod
        .number()
        .min(generateRetentionDraftsResponseStatsVerifiedMin),
      new_ltp_players: zod
        .number()
        .min(generateRetentionDraftsResponseStatsNewLtpPlayersMin),
      created: zod.number().min(generateRetentionDraftsResponseStatsCreatedMin),
      skipped: zod.number().min(generateRetentionDraftsResponseStatsSkippedMin),
      needs_context: zod
        .number()
        .min(generateRetentionDraftsResponseStatsNeedsContextMin),
      manual_edit: zod
        .number()
        .min(generateRetentionDraftsResponseStatsManualEditMin),
      error_count: zod
        .number()
        .min(generateRetentionDraftsResponseStatsErrorCountMin),
      errors: zod
        .array(zod.string())
        .describe(
          "Compatibility detail array matching top-level errors; use error_count for the count",
        ),
      skipped_by_reason: zod.object({
        no_phone: zod
          .number()
          .min(generateRetentionDraftsResponseStatsSkippedByReasonNoPhoneMin),
        opted_out: zod
          .number()
          .min(generateRetentionDraftsResponseStatsSkippedByReasonOptedOutMin),
        duplicate: zod
          .number()
          .min(generateRetentionDraftsResponseStatsSkippedByReasonDuplicateMin),
        holdout: zod
          .number()
          .min(generateRetentionDraftsResponseStatsSkippedByReasonHoldoutMin),
        marketing_consent: zod
          .number()
          .min(
            generateRetentionDraftsResponseStatsSkippedByReasonMarketingConsentMin,
          ),
        missing_player: zod
          .number()
          .min(
            generateRetentionDraftsResponseStatsSkippedByReasonMissingPlayerMin,
          ),
        invalid_trigger: zod
          .number()
          .min(
            generateRetentionDraftsResponseStatsSkippedByReasonInvalidTriggerMin,
          ),
        out_of_window: zod
          .number()
          .min(
            generateRetentionDraftsResponseStatsSkippedByReasonOutOfWindowMin,
          ),
        already_returned: zod
          .number()
          .min(
            generateRetentionDraftsResponseStatsSkippedByReasonAlreadyReturnedMin,
          ),
      }),
    })
    .describe(
      "found counts first-ever LTP attendance candidates in the conservative raw-date window; verified counts PodPlay-corroborated LTP triggers including out-of-window triggers; new_ltp_players counts verified triggers inside the effective date window. For a completed generation, created plus skipped plus needs_context plus manual_edit plus error_count accounts for found candidates.",
    ),
  coupon_check: zod
    .object({
      code: zod.string().nullable(),
      valid: zod.boolean().nullable(),
      warning: zod.string().nullable(),
    })
    .describe(
      "Null values mean no promo coupon is configured. A configured coupon is checked even when there are no candidate players.",
    ),
  drafts: zod
    .array(
      zod.object({
        candidate_id: zod.string(),
        player_id: zod.string(),
        player_name: zod.string().nullable(),
        status: zod.enum([
          "drafted",
          "needs_context",
          "manual_edit",
          "skipped",
        ]),
        reason: zod.string().nullable(),
        body: zod
          .string()
          .nullable()
          .describe(
            "Exact persisted draft body; null when context, validation, or already-returned checks block drafting",
          ),
        context: zod
          .object({
            variant: zod
              .enum(["with_program", "no_program"])
              .optional()
              .describe(
                "Generation variant. Optional only for legacy contexts.",
              ),
            player_first_name: zod.string().optional(),
            trigger: zod
              .object({
                event_id: zod.string(),
                name: zod.string(),
                date: zod.string(),
              })
              .optional(),
            next_program: zod
              .union([
                zod.object({
                  event_id: zod.string(),
                  name: zod.string(),
                  start_time: zod.string(),
                  date: zod.string(),
                  time: zod.string(),
                  signup_url: zod.string(),
                  spots_remaining: zod.number().optional(),
                }),
                zod.null(),
              ])
              .optional(),
            booking_url: zod
              .literal("https://pbclub.podplay.app")
              .optional()
              .describe(
                "Exact approved booking-page URL supplied for no_program contexts; optional on legacy with_program contexts.",
              ),
            forbidden_program_names: zod
              .array(zod.string())
              .optional()
              .describe(
                "Event, trigger, and configured program names that no_program text must not mention. Required for new no_program contexts; optional on legacy contexts.",
              ),
            booked_event: zod
              .union([
                zod.object({
                  event_id: zod.string(),
                  name: zod.string(),
                  start_time: zod.string(),
                  date: zod.string(),
                  time: zod.string(),
                  signup_url: zod.string(),
                  spots_remaining: zod.number().optional(),
                }),
                zod.null(),
              ])
              .optional(),
            classmates_signed_up: zod
              .number()
              .min(
                generateRetentionDraftsResponseDraftsItemContextClassmatesSignedUpMin,
              )
              .optional(),
            already_booked: zod.boolean().optional(),
            promo: zod
              .object({
                code: zod.string().optional(),
                offer_text: zod.string().optional(),
              })
              .nullish(),
            coupon_warning: zod.string().nullish(),
            evaluated_at: zod.string().optional(),
            stale: zod
              .boolean()
              .optional()
              .describe(
                "True when the candidate was generated with a test lookback longer than the production default.",
              ),
            lookback_days: zod
              .number()
              .min(1)
              .max(
                generateRetentionDraftsResponseDraftsItemContextLookbackDaysMax,
              )
              .optional(),
            reason: zod.string().nullish(),
            errors: zod
              .array(zod.unknown())
              .optional()
              .describe(
                "Lookup failures; entries may be strings or structured error objects.",
              ),
            validation_errors: zod.array(zod.string()).optional(),
            date_phrase: zod
              .string()
              .nullish()
              .describe(
                "Timing provenance retained in context. Required for new no_program contexts; no_program copy uses NOW\/present-time framing following a Learn to Play thank-you.",
              ),
            send_date: zod.string().nullish(),
            send_date_et: zod.string().nullish(),
            next_program_day: zod.string().nullish(),
            generated_preview: zod.string().nullish(),
            diagnostics: zod.unknown().optional(),
            ltp_text: zod
              .object({
                step: zod.union([zod.literal(1), zod.literal(2)]),
                seed_nonce: zod
                  .number()
                  .min(
                    generateRetentionDraftsResponseDraftsItemContextLtpTextSeedNonceMin,
                  ),
                slot_indices: zod.record(
                  zod.string(),
                  zod
                    .number()
                    .min(
                      generateRetentionDraftsResponseDraftsItemContextLtpTextSlotIndicesMinOne,
                    ),
                ),
                opener: zod.string(),
                slot_templates: zod.record(zod.string(), zod.string()),
                ltp_date: zod.string(),
                when: zod.string().nullable(),
              })
              .nullish()
              .describe(
                "Selected template slots and code-filled facts for deterministic LTP copy; absent on legacy model-built drafts.",
              ),
          })
          .describe(
            "Context fields are optional for compatibility with legacy stored candidates. A missing variant is interpreted as with_program only when next_program is present; incomplete legacy contexts do not imply no_program.",
          ),
        step: zod.union([zod.literal(1), zod.literal(2)]).optional(),
        sequence_status: zod
          .union([
            zod.literal("active"),
            zod.literal("paused_reply"),
            zod.literal("exited_booked"),
            zod.literal("exited_opt_out"),
            zod.literal("completed"),
            zod.literal(null),
          ])
          .nullish(),
        validation_errors: zod.array(zod.string()).optional(),
      }),
    )
    .describe("Only candidates newly created by this call"),
});

